-- Explicit customer teaching content is separate from internal completion facts.
grant create on schema api,app_private to git_tutor_commands;
create table app_private.learning_records(id uuid primary key default gen_random_uuid(),occurrence_id uuid not null references app_private.occurrences(id),learner_id uuid references app_private.learners(id),version integer not null default 0 check(version>=0),unique nulls not distinct(occurrence_id,learner_id));
create table app_private.learning_record_revisions(id uuid primary key default gen_random_uuid(),record_id uuid not null references app_private.learning_records(id),version integer not null check(version>0),content text not null check(length(btrim(content))between 1 and 5000),actor_account_id uuid not null references app_private.accounts(id),replaces_revision_id uuid references app_private.learning_record_revisions(id),command_id uuid not null,published_at timestamptz not null default now(),unique(record_id,version));
create function api.publish_learning_record(p_occurrence_id uuid,p_learner_id uuid,p_content text,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();o app_private.occurrences%rowtype;r app_private.learning_records%rowtype;ctx jsonb;revision uuid;prior uuid;begin
 select * into o from app_private.occurrences where id=p_occurrence_id for update;if o.id is null then raise exception'NOT_FOUND';end if;perform app_private.delivery_assert_scope(actor,o.id);if app_private.has_role(actor,'admin')then perform app_private.require_role(actor,'admin');end if;
 if o.state<>'completed'or not exists(select 1 from app_private.completions c join app_private.completion_approvals a on a.completion_id=c.id where c.occurrence_id=o.id)then raise exception'STATE_CONFLICT';end if;
 if p_content is null or length(btrim(p_content))not between 1 and 5000 or p_expected_version is null or p_expected_version<0 then raise exception'VALIDATION_ERROR';end if;
 if p_learner_id is not null and not exists(select 1 from app_private.enrollments e where e.occurrence_id=o.id and e.learner_id=p_learner_id and e.state='confirmed')then raise exception'NOT_FOUND';end if;
 ctx:=app_private.booking_begin(actor,'publish_learning_record',jsonb_build_object('occurrence_id',o.id,'learner_id',p_learner_id,'content',btrim(p_content),'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 insert into app_private.learning_records(occurrence_id,learner_id)values(o.id,p_learner_id)on conflict do nothing;select * into r from app_private.learning_records where occurrence_id=o.id and learner_id is not distinct from p_learner_id for update;if r.version<>p_expected_version then raise exception'VERSION_CONFLICT';end if;
 select id into prior from app_private.learning_record_revisions where record_id=r.id and version=r.version;
 insert into app_private.learning_record_revisions(record_id,version,content,actor_account_id,replaces_revision_id,command_id)values(r.id,r.version+1,btrim(p_content),actor,prior,(ctx->>'command_id')::uuid)returning id into revision;
 update app_private.learning_records set version=version+1 where id=r.id returning * into r;
 return app_private.booking_finish(ctx,r.id,r.version,jsonb_build_object('record_id',r.id,'revision_id',revision,'occurrence_id',o.id,'learner_id',p_learner_id),'learning_record_published',jsonb_build_object('record_id',r.id,'revision_id',revision,'occurrence_id',o.id,'learner_id',p_learner_id));end$$;
create function app_private.learning_record_dto(p_record uuid,p_history boolean)returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin select jsonb_build_object('record_id',r.id,'learner_id',r.learner_id,'revision_id',v.id,'version',v.version,'content',v.content,'published_at',v.published_at)into result from app_private.learning_records r join app_private.learning_record_revisions v on v.record_id=r.id and v.version=r.version where r.id=p_record;if p_history and result is not null then result:=result||jsonb_build_object('revisions',(select jsonb_agg(jsonb_build_object('revision_id',v.id,'version',v.version,'content',v.content,'published_at',v.published_at)order by v.version desc)from app_private.learning_record_revisions v where v.record_id=p_record));end if;return result;end$$;
create function api.get_learning_records(p_occurrence_id uuid,p_view text,p_learner_id uuid default null)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();o app_private.occurrences%rowtype;result jsonb;teacher boolean:=p_view in('tutor','admin');begin
 if p_view is null or p_view not in('customer','tutor','admin')then raise exception'VALIDATION_ERROR';end if;
 if p_view='customer'then if p_learner_id is null then raise exception'VALIDATION_ERROR';end if;perform app_private.assert_learner_scope(actor,p_learner_id,'materials');if not exists(select 1 from app_private.enrollments e where e.occurrence_id=p_occurrence_id and e.learner_id=p_learner_id and e.state='confirmed')then raise exception'NOT_FOUND';end if;
 else if p_view='admin'then perform app_private.require_role(actor,'admin');else perform app_private.require_role(actor,'tutor');end if;perform app_private.delivery_assert_scope(actor,p_occurrence_id);if p_learner_id is not null then raise exception'VALIDATION_ERROR';end if;end if;
 select * into o from app_private.occurrences where id=p_occurrence_id;if o.id is null then raise exception'NOT_FOUND';end if;
 result:=jsonb_build_object('occurrence_id',o.id,'view',p_view,'can_publish',teacher and o.state='completed'and exists(select 1 from app_private.completions c join app_private.completion_approvals a on a.completion_id=c.id where c.occurrence_id=o.id),'group_summary',(select app_private.learning_record_dto(r.id,teacher)from app_private.learning_records r where r.occurrence_id=o.id and r.learner_id is null),'feedback',(select coalesce(jsonb_agg(app_private.learning_record_dto(r.id,teacher)order by r.learner_id),'[]')from app_private.learning_records r where r.occurrence_id=o.id and r.learner_id is not null and(teacher or r.learner_id=p_learner_id)));
 if teacher then result:=result||jsonb_build_object('roster',(select coalesce(jsonb_agg(jsonb_build_object('learner_id',l.id,'display_name',p.display_name)order by p.display_name,l.id),'[]')from app_private.enrollments e join app_private.learners l on l.id=e.learner_id join app_private.people p on p.id=l.person_id where e.occurrence_id=o.id and e.state='confirmed'));end if;return result;end$$;
alter function app_private.notification_kind(text)rename to notification_kind_pre_learning_20261113;
create function app_private.notification_kind(p_event text)returns text language sql immutable set search_path=''as $$select case when p_event='learning_record_published'then'completion'else app_private.notification_kind_pre_learning_20261113(p_event)end$$;
alter function app_private.notification_recipients(uuid)rename to notification_recipients_pre_learning_20261113;
create function app_private.notification_recipients(p_event_id uuid)returns table(account_id uuid,audience text,content jsonb)language plpgsql volatile security definer set search_path=''as $$declare e app_private.domain_events%rowtype;r app_private.learning_records%rowtype;begin
 select * into e from app_private.domain_events where id=p_event_id;if e.event_type is distinct from'learning_record_published'then return query select *from app_private.notification_recipients_pre_learning_20261113(p_event_id);return;end if;
 select h.*into r from app_private.learning_records h join app_private.learning_record_revisions v on v.record_id=h.id where h.id=e.aggregate_id and v.id=app_private.notification_uuid(e.payload->>'revision_id');if r.id is null then return;end if;
 return query with roster as(select n.learner_id,l.account_id from app_private.enrollments n join app_private.learners l on l.id=n.learner_id where n.occurrence_id=r.occurrence_id and n.state='confirmed'and(r.learner_id is null or n.learner_id=r.learner_id)),recipients as(select s.account_id from roster s union select g.guardian_account_id from app_private.guardian_links g join roster s on s.learner_id=g.learner_id where g.revoked_at is null and g.valid_from<=now()and g.valid_until>now()and 'materials'=any(g.scopes)and 'notifications'=any(g.scopes))select a.id,'customer'::text,jsonb_build_object('kind','completion','locale',a.locale,'audience','customer','action_path','/learn/bookings','starts_at',null)from recipients c join app_private.accounts a on a.id=c.account_id where a.active;end$$;
do $$declare t text;f record;begin foreach t in array array['learning_records','learning_record_revisions']loop execute format('alter table app_private.%I enable row level security',t);execute format('create policy commands_access on app_private.%I to git_tutor_commands using(true)with check(true)',t);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t);execute format('grant select,insert on app_private.%I to git_tutor_commands',t);end loop;
 for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and p.proname=any(array['publish_learning_record','get_learning_records','learning_record_dto','notification_kind','notification_recipients','notification_kind_pre_learning_20261113','notification_recipients_pre_learning_20261113'])loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
grant update on app_private.learning_records to git_tutor_commands;
create trigger immutable_row before update or delete on app_private.learning_record_revisions for each row execute function app_private.reject_immutable_change();
revoke create on schema api,app_private from git_tutor_commands;
